export const RELEASE_CANDIDATE_WORKFLOW_PIN=RELEASE_CANDIDATE_SOURCE_PINS['.github/workflows/own-payroll-full-capacity.yml'];
export function projectReleaseCandidateWorkflowToParent(path,value){
 assert.equal(typeof path,'string');assert.ok(Buffer.isBuffer(value));
 const pin=RELEASE_CANDIDATE_SOURCE_PINS[path];if(!pin)return value;
 assert.equal(value.length,pin.afterBytes,'CANDIDATE_WORKFLOW_CURRENT_BYTES');
 assert.equal(hash(value),pin.after,'CANDIDATE_WORKFLOW_CURRENT_HASH');
 let source=value;
 for(const op of [...pin.inverse].reverse()){
  const after=Buffer.from(op.after,'base64'),before=Buffer.from(op.before,'base64');
  assert.deepEqual(source.subarray(op.offset,op.offset+after.length),after,'CANDIDATE_WORKFLOW_EXACT_SPAN');
  source=Buffer.concat([source.subarray(0,op.offset),before,source.subarray(op.offset+after.length)]);
 }
 assert.equal(source.length,pin.beforeBytes,'CANDIDATE_WORKFLOW_PARENT_BYTES');
 assert.equal(hash(source),pin.before,'CANDIDATE_WORKFLOW_PARENT_HASH');return source;
}
